-- A reviewed departure fences every current responsibility and authorization before moving anything.
CREATE TABLE peg_departure_revision(id INTEGER PRIMARY KEY CHECK(id=1),value INTEGER NOT NULL);
INSERT INTO peg_departure_revision VALUES(1,1);
CREATE TABLE peg_departure_guards(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,actor_id TEXT NOT NULL);
CREATE TRIGGER peg_departure_check BEFORE INSERT ON peg_departure_guards BEGIN
 SELECT CASE WHEN NEW.revision<>(SELECT value FROM peg_departure_revision WHERE id=1) OR NOT EXISTS(SELECT 1 FROM oa_operators WHERE id=NEW.actor_id AND status='active' AND role IN ('owner','admin')) THEN RAISE(ABORT,'departure_review_changed') END;
END;
DROP TRIGGER peg_delivery_immutable;
CREATE TRIGGER peg_delivery_immutable BEFORE UPDATE ON peg_delivery_records WHEN NEW.baseline<>OLD.baseline OR NEW.proposal<>OLD.proposal OR (OLD.status<>'pending' AND NOT EXISTS(SELECT 1 FROM peg_departure_guards)) BEGIN SELECT RAISE(ABORT,'immutable_delivery_record'); END;
DROP TRIGGER peg_goal_valid_owner_update;
CREATE TRIGGER peg_goal_valid_owner_update BEFORE UPDATE OF owner_id,scope ON peg_goals
WHEN NOT (NEW.owner_id='' AND EXISTS(SELECT 1 FROM peg_departure_guards)) AND NOT EXISTS (SELECT 1 FROM oa_operators o LEFT JOIN peg_workspace_members m ON m.operator_id=o.id AND m.workspace_id=NEW.workspace_id WHERE o.id=NEW.owner_id AND o.status='active' AND (o.role IN ('owner','admin') OR m.role IN ('manager','member') OR NEW.scope='personal' AND m.role='analyst'))
BEGIN SELECT RAISE(ABORT,'goal_owner_human_required'); END;
